const crypto = require('crypto');
// Firma de Reymen (entrada /api/webhooks/n8n/*): sha256= + HMAC-SHA256 hex de "<timestamp>.<cuerpo>" con la llave del cliente.
function firmar(llave, body) {
  const ts = String(Date.now());
  return { ts, sig: 'sha256=' + crypto.createHmac('sha256', llave).update(ts + '.' + body).digest('hex') };
}
// Cuerpo crudo que llegó al webhook (opción "Raw Body"), para verificar firmas byte por byte.
function crudo(item) {
  return item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body || {});
}
// Verifica que el aviso venga de Reymen (firma de plataforma con N8N_WEBHOOK_SECRET y hora dentro de ±5 min).
function verificarReymen(item) {
  const secret = $env.N8N_WEBHOOK_SECRET;
  const h = item.json.headers || {};
  const raw = crudo(item);
  const ts = String(h['x-reymen-timestamp'] || '');
  const sig = String(h['x-reymen-signature'] || '');
  const esperado = 'sha256=' + crypto.createHmac('sha256', secret || '').update(ts + '.' + raw).digest('hex');
  if (!secret || !ts || Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000 || sig.length !== esperado.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(esperado))) {
    throw new Error('Firma de Reymen inválida');
  }
  return JSON.parse(raw);
}

// Teléfono a formato internacional (+52 + 10 dígitos para México; otros países ya con su lada).
function e164(raw) {
  const s = String(raw || '').replace(/^whatsapp:/, '');
  const d = s.replace(/\D/g, '');
  if (d.length === 10) return '+52' + d;
  if (d.length === 13 && d.startsWith('521')) return '+52' + d.slice(3);
  if (s.trim().startsWith('+') && d.length >= 11) return '+' + d;
  if (d.length === 12 && d.startsWith('52')) return '+' + d;
  return null;
}
// Firma de Twilio (X-Twilio-Signature): base64 de HMAC-SHA1 de la URL pública + cada parámetro (ordenados) con el Auth Token.
function twilioValido(cfg, url, params, firma) {
  if (!cfg.twilioAuthToken) return true; // sin token configurado no se verifica (ver la guía)
  const data = url + Object.keys(params).sort().map((k) => k + params[k]).join('');
  const esperado = crypto.createHmac('sha1', cfg.twilioAuthToken).update(Buffer.from(data, 'utf-8')).digest('base64');
  return !!firma && firma.length === esperado.length && crypto.timingSafeEqual(Buffer.from(firma), Buffer.from(esperado));
}
const twilioUrl = (cfg, c) => 'https://api.twilio.com/2010-04-01/Accounts/' + (c.twilioAccountSid || cfg.twilioAccountSid) + '/Messages.json';

// CONFIGURACIÓN (lo único que se edita). Mensajes de las automatizaciones de Reymen (bienvenida, cumpleaños, segunda
// visita, recuperación, opinión después de la visita, recompensa de lealtad) por WhatsApp con Twilio.
// - WhatsApp exige PLANTILLA APROBADA para escribirle primero a un cliente. Crea cada una en Twilio (Content Template
//   Builder), espera la aprobación y pega su contentSid abajo. variables = qué dato de Reymen va en {{1}}, {{2}}…
// - Una automatización cuya plantilla no esté aquí se registra en Reymen como «omitida» (nunca se manda texto suelto).
// - clientes: orgId de Reymen → su número de WhatsApp en Twilio. El token de Twilio va en la credencial "Twilio".
const cfg = {
  twilioAccountSid: 'ACxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
  clientes: {
    'PEGA_AQUI_EL_ID_DE_LA_ORGANIZACION': { whatsapp: '+528100000000' },
  },
  plantillas: {
    welcome_new_customer_v1:   { contentSid: '', variables: ['name', 'businessName'] },
    second_visit_v1:           { contentSid: '', variables: ['name', 'businessName'] },
    birthday_campaign_v1:      { contentSid: '', variables: ['name', 'businessName'] },
    customer_recovery_v1:      { contentSid: '', variables: ['name', 'businessName', 'daysSince'] },
    post_visit_feedback_v1:    { contentSid: '', variables: ['name', 'businessName', 'feedbackUrl'] },
    loyalty_reward_unlocked_v1:{ contentSid: '', variables: ['name', 'businessName', 'rewardName'] },
  },
};

const msg = verificarReymen($input.first());
const base = { callbackUrl: msg.callback.url, token: msg.callback.token, executionId: msg.execution.id };
const omitir = (motivo) => [{ json: { ...base, enviar: false, status: 'skipped', error: motivo } }];
const c = cfg.clientes[msg.organization.id];
const r = msg.recipient || {};
const plantilla = cfg.plantillas[(msg.content || {}).templateKey];
if (r.channel !== 'whatsapp') return omitir('canal_no_soportado:' + r.channel);
if (!c) return omitir('cliente_sin_numero_de_whatsapp');
if (!plantilla || !plantilla.contentSid) return omitir('plantilla_sin_configurar:' + (msg.content || {}).templateKey);
const to = e164(r.phone);
if (!to) return omitir('telefono_invalido');
const vars = (msg.content || {}).variables || {};
const contentVariables = {};
plantilla.variables.forEach((k, i) => { contentVariables[String(i + 1)] = String(vars[k] || (k === 'name' ? 'hola' : '')).trim() || '-'; });
const form = new URLSearchParams({ From: 'whatsapp:' + e164(c.whatsapp), To: 'whatsapp:' + to, ContentSid: plantilla.contentSid, ContentVariables: JSON.stringify(contentVariables) });
return [{ json: { ...base, enviar: true, twilioUrl: twilioUrl(cfg, c), form: form.toString() } }];

// Le dice a Reymen cómo terminó: enviado (Twilio lo aceptó), fallido u omitido. Firma de plataforma.
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
const prep = $('Verificar y preparar').first().json;
const res = $input.first().json;
let status = prep.enviar ? 'failed' : 'skipped';
let providerMessageId, error = prep.error;
if (prep.enviar && res.sid && !res.error_code) { status = 'sent'; providerMessageId = res.sid; error = undefined; }
else if (prep.enviar) error = 'twilio:' + (res.code || res.error_code || '') + ' ' + (res.message || res.error_message || 'sin respuesta');
const body = JSON.stringify({ executionId: prep.executionId, token: prep.token, status, ...(providerMessageId ? { providerMessageId } : {}), ...(error ? { error: String(error).slice(0, 300) } : {}) });
const ts = String(Date.now());
const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + body).digest('hex');
return [{ json: { url: prep.callbackUrl, body, cbTs: ts, cbSig: sig } }];
